import{_ as l,a0 as t,w as o,s as r,ao as d,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Linux 中遨遊手冊頁的海洋 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中遨遊手冊頁的海洋 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中遨遊手冊頁的海洋 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中遨遊手冊頁的海洋 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200211 Navigating man pages in Linux","title":"在 Linux 中遨遊手冊頁的海洋","tag":"202004","desc":""},"relativePath":"202004/20200211 Navigating man pages in Linux.md","filePath":"[post].md"}'),c={name:"202004/20200211 Navigating man pages in Linux.md"};function u(h,s,g,m,k,b){const n=t("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="在-linux-中遨遊手冊頁的海洋" tabindex="-1">在 Linux 中遨遊手冊頁的海洋 <a class="header-anchor" href="#在-linux-中遨遊手冊頁的海洋" aria-label="Permalink to “在 Linux 中遨遊手冊頁的海洋”">​</a></h1><blockquote><p>Linux 系統上的手冊頁可以做的不僅僅是提供特定命令的信息。它們可以幫助你發現你沒有意識到的命令。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/10/field-note_play-book_playbook_map_navigation_journey_by-hello-i-m-nik-via-unsplash-100813507-large.jpg" alt="Hello I&#39;m Nik"></p><p>手冊頁提供了關於 Linux 命令的基本信息，很多用户經常參考它，但手冊頁的內容比我們很多人意識到的要多得多。</p><p>你總是可以輸入一個像 <code>man who</code> 這樣的命令，然後得到 <code>who</code> 命令的工作原理的漂亮描述，但是探索你可能不知道的命令可能會更有啓發。例如，你可以使用 <code>man</code> 命令來幫助找到一些處理非常具有挑戰性的任務的命令，或者顯示一些選項，這些選項可以幫助你以新的更好的方式使用你已經知道的命令。</p><p>讓我們來瀏覽一些選項，看看最終的結果是什麼。</p><h3 id="用-man-去識別命令" tabindex="-1">用 man 去識別命令 <a class="header-anchor" href="#用-man-去識別命令" aria-label="Permalink to “用 man 去識別命令”">​</a></h3><p><code>man</code> 命令可以幫助你按主題查找命令。例如，如果你要找一個計算文件中的行數的命令，你可以提供一個關鍵字。在下面的例子中，我們把關鍵字 “count” 放在了引號中，並添加了空格，這樣我們就不會得到與 “accounts” 或 “accounting” 相關的命令，而是得到那些可以為我們做一些計算的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man -k &#39; count &#39;</span></span>
<span class="line"><span>anvil (8postfix)     - Postfix session count and request rate control</span></span>
<span class="line"><span>cksum (1)            - checksum and count the bytes in a file</span></span>
<span class="line"><span>sum (1)              - checksum and count the blocks in a file</span></span>
<span class="line"><span>timer_getoverrun (2) - get overrun count for a POSIX per-process timer</span></span></code></pre></div><p>為了顯示與新用户賬户相關的命令，我們可以嘗試使用這樣的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man -k &quot;new user&quot;</span></span>
<span class="line"><span>newusers (8)         - update and create new users in batch</span></span>
<span class="line"><span>useradd (8)          - create a new user or update default new user information</span></span>
<span class="line"><span>zshroadmap (1)       - informal introduction to the zsh manual The Zsh Manual, …</span></span></code></pre></div><p>需要説明的是，上面的第三項只是提到 “new users” 類似的內容，並不是設置、刪除或配置用户賬號的命令。<code>man</code> 命令只是在命令描述中匹配了一些詞，作用很像 <code>apropos</code> 命令。注意上面列出的每個命令後面的括號中的數字。這些數字與包含這些命令的手冊頁的分區有關。</p><h3 id="確定手冊頁的分區" tabindex="-1">確定手冊頁的分區 <a class="header-anchor" href="#確定手冊頁的分區" aria-label="Permalink to “確定手冊頁的分區”">​</a></h3><p><code>man</code> 命令的分區將其內容劃分為不同的類別。要列出這些類別，請鍵入 <code>man man</code>，並查看類似下面的描述。你的系統中很可能沒有第 9 分區的命令。</p><ul><li><code>1</code>：可執行程序或 shell 命令</li><li><code>2</code>：系統調用（內核提供的函數）</li><li><code>3</code>：庫調用（程序庫內的函數）</li><li><code>4</code>：特殊文件（通常在可以 <code>/dev</code> 中找到）</li><li><code>5</code>：文件格式和慣例，例如 <code>/etc/passwd</code></li><li><code>6</code>：遊戲</li><li><code>7</code>：雜項（包括宏包和約定），例如 <code>man</code>(7)、<code>groff</code>(7)</li><li><code>8</code>：系統管理命令（通常只由 root 用户使用）</li><li><code>9</code>：內核例程（非標準）</li></ul><p>手冊頁涵蓋了比我們通常認為的“命令”更多的內容。從上面的描述中可以看到，它們涵蓋了系統調用、庫調用、特殊文件等等。</p><p>下面的列表顯示了 Linux 系統中的手冊頁的實際存儲位置。這些目錄上的日期會有所不同，因為隨着更新，其中一些分區會有新的內容，而另一些則不會。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ld /usr/share/man/man?</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  98304 Feb  5 16:27 /usr/share/man/man1</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  65536 Oct 23 17:39 /usr/share/man/man2</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 270336 Nov 15 06:28 /usr/share/man/man3</span></span>
<span class="line"><span>drwxr-xr-x 2 root root   4096 Feb  4 10:16 /usr/share/man/man4</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  28672 Feb  5 16:25 /usr/share/man/man5</span></span>
<span class="line"><span>drwxr-xr-x 2 root root   4096 Oct 23 17:40 /usr/share/man/man6</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  20480 Feb  5 16:25 /usr/share/man/man7</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  57344 Feb  5 16:25 /usr/share/man/man8</span></span></code></pre></div><p>注意，為了節省空間，手冊頁文件一般都是 gzip 壓縮的。每當你使用 <code>man</code> 命令時，<code>man</code> 命令會根據需要解壓。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /usr/share/man/man1 | head -10</span></span>
<span class="line"><span>total 12632</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root      9 Sep  5 06:38 [.1.gz -&gt; test.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root    563 Nov  7 05:07 2to3-2.7.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root    592 Apr 23  2016 411toppm.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   2866 Aug 14 10:36 a2query.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   2361 Sep  9 15:13 aa-enabled.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   2675 Sep  9 15:13 aa-exec.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   1142 Apr  3  2018 aaflip.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   3847 Aug 14 10:36 ab.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   2378 Aug 23  2018 ac.1.gz</span></span></code></pre></div><h3 id="按分區列出的手冊頁" tabindex="-1">按分區列出的手冊頁 <a class="header-anchor" href="#按分區列出的手冊頁" aria-label="Permalink to “按分區列出的手冊頁”">​</a></h3><p>即使只看第 1 分區的前 10 個手冊頁（如上所示），你也可能會看到一些新的命令 —— 也許是 <code>a2query</code> 或 <code>aaflip</code>（如上所示）。</p><p>探索命令的更好策略是按分區列出命令，不查看文件本身，而是使用 <code>man</code> 命令向你顯示命令並提供每個命令的簡要説明。</p><p>在下面的命令中，<code>-s 1</code> 指示 <code>man</code> 顯示第 1 分區中的命令信息。<code>-k .</code> 使該命令對所有命令都有效，而不是指定一個特定的關鍵字；如果沒有這個，<code>man</code> 命令就會回過頭來問：“你想要什麼手冊頁？”所以，使用關鍵字來選擇一組相關的命令，或者使用點來顯示一個分區中的所有命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man -s 1 -k .</span></span>
<span class="line"><span>2to3-2.7 (1)         - Python2 to Python3 converter</span></span>
<span class="line"><span>411toppm (1)         - convert Sony Mavica .411 image to ppm</span></span>
<span class="line"><span>as (1)               - the portable GNU assembler.</span></span>
<span class="line"><span>baobab (1)           - A graphical tool to analyze disk usage</span></span>
<span class="line"><span>busybox (1)          - The Swiss Army Knife of Embedded Linux</span></span>
<span class="line"><span>cmatrix (1)          - simulates the display from &quot;The Matrix&quot;</span></span>
<span class="line"><span>expect_dislocate (1) - disconnect and reconnect processes</span></span>
<span class="line"><span>red (1)              - line-oriented text editor</span></span>
<span class="line"><span>enchant (1)          - a spellchecker</span></span>
<span class="line"><span>…</span></span></code></pre></div><h3 id="有多少手冊頁" tabindex="-1">有多少手冊頁？ <a class="header-anchor" href="#有多少手冊頁" aria-label="Permalink to “有多少手冊頁？”">​</a></h3><p>如果你對每個分區中有多少手冊頁感到好奇，可以使用以下命令按分區對它們進行計數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for num in {1..8}</span></span>
<span class="line"><span>&gt; do</span></span>
<span class="line"><span>&gt;   man -s $num -k . | wc -l</span></span>
<span class="line"><span>&gt; done</span></span>
<span class="line"><span>2382</span></span>
<span class="line"><span>493</span></span>
<span class="line"><span>2935</span></span>
<span class="line"><span>53</span></span>
<span class="line"><span>441</span></span>
<span class="line"><span>11</span></span>
<span class="line"><span>245</span></span>
<span class="line"><span>919</span></span></code></pre></div><p>確切的數量可能有所不同，但是大多數 Linux 系統的命令數量差不多。如果我們使用命令將這些數字加在一起，我們可以看到運行該命令的系統上有將近 7500 個手冊頁。有很多命令，系統調用等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for num in {1..8}</span></span>
<span class="line"><span>&gt; do</span></span>
<span class="line"><span>&gt;     num=\`man -s $num -k . | wc -l\`</span></span>
<span class="line"><span>&gt;     tot=\`expr $num + $tot\`</span></span>
<span class="line"><span>&gt;     echo $tot</span></span>
<span class="line"><span>&gt; done</span></span>
<span class="line"><span>2382</span></span>
<span class="line"><span>2875</span></span>
<span class="line"><span>5810</span></span>
<span class="line"><span>5863</span></span>
<span class="line"><span>6304</span></span>
<span class="line"><span>6315</span></span>
<span class="line"><span>6560</span></span>
<span class="line"><span>7479            &lt;=== total</span></span></code></pre></div><p>閲讀手冊頁可以學到很多東西，但是以其他方式瀏覽手冊頁可以幫助你瞭解系統上可能不知道的命令。</p><hr>`,32)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3519853/navigating-man-pages-in-linux.html"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3519853/navigating-man-pages-in-linux.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=l(c,[["render",u]]);export{w as __pageData,y as default};
